.brand-text { display: flex; flex-direction: column; line-height: 1.15; }
.brand-name { font-weight: 700; font-size: 15px; letter-spacing: -0.01em; }
.brand-sub { font-size: 11px; color: var(--ink-3); letter-spacing: 0.04em; text-transform: uppercase; }

.searchbar {
  position: relative;
  flex: 1; max-width: 760px;
  display: flex; align-items: center;
}
.search-glyph {
  position: absolute; left: 12px;
  width: 15px; height: 15px;
  color: var(--ink-3); pointer-events: none;
}
#q {
  width: 100%;
  font: 14px var(--sans);
  color: var(--ink);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--rad);
  padding: 9px 64px 9px 36px;
}
#q::placeholder { color: var(--ink-3); }
#q:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-weak);
  background: var(--surface);
}
.q-clear {
  position: absolute; right: 40px;
  width: 20px; height: 20px;
  border-radius: 50%;
  color: var(--ink-2);
  font-size: 15px; line-height: 20px; text-align: center;
}
.q-clear:hover { background: var(--border-soft); }
.kbd-hint {
  position: absolute; right: 10px;
  pointer-events: none;
}
.snapshot { margin-left: auto; font-size: 12px; color: var(--ink-3); white-space: nowrap; }

/* ── breadcrumb_strip ──────────────────────────────────────────────────── */
.crumbs {
  display: flex; align-items: center; gap: 6px;
  min-height: 34px;
  padding: 3px 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  white-space: nowrap;
}
.crumb {
  color: var(--ink-2);
  padding: 3px 8px;
  border-radius: var(--rad);
}
.crumb:hover { background: var(--border-soft); color: var(--ink); }
.crumb.is-active { color: var(--accent-ink); font-weight: 600; background: var(--accent-weak); }
.crumb-sep { color: var(--ink-3); }
.crumb-hint { color: var(--ink-3); font-size: 12px; font-style: italic; }
.crumb-chip {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12px;
  color: var(--accent-ink);
  background: var(--accent-weak);
  border: 1px solid #c6dcff;
  border-radius: 999px;
  padding: 2px 9px;
}
.crumb-chip:hover { border-color: var(--accent); }
.crumb-chip .x { font-weight: 700; }
.crumb-clear {
  margin-left: auto;
  font-size: 12px;
  color: var(--ink-2);
  padding: 3px 10px;
  border: 1px solid var(--border);
  border-radius: var(--rad);
  background: var(--surface);
}
.crumb-clear:hover { color: var(--out-ink); border-color: var(--out-ink); }

/* ── layout ────────────────────────────────────────────────────────────── */
.layout {
  display: grid;
  grid-template-columns: 288px minmax(0, 1fr) 336px;
  min-height: 0;
}
.rail, .results, .inspector { min-height: 0; overflow-y: auto; }

/* ── filter_rail ───────────────────────────────────────────────────────── */
.rail {
  background: var(--surface);
  border-right: 1px solid var(--border);
  padding: 12px 12px 24px;
}
.rail-h {
  margin: 18px 6px 7px;
  font-size: 11px; font-weight: 700;
  letter-spacing: 0.07em; text-transform: uppercase;
  color: var(--ink-3);
}
.cat-item { margin-bottom: 1px; }
.cat-row, .fam-row {
  width: 100%;
  display: grid;
  grid-template-columns: 16px 1fr auto;
  align-items: center; gap: 6px;
  text-align: left;
  padding: 6px 8px;
  border-radius: var(--rad);
  color: var(--ink);
}
.fam-row { grid-template-columns: 1fr auto; padding-left: 26px; }
.cat-row:hover, .fam-row:hover { background: var(--border-soft); }
.cat-row.is-active, .fam-row.is-active {
  background: var(--accent-weak);
  color: var(--accent-ink);
  font-weight: 600;
}
.cat-row .chev { color: var(--ink-3); font-size: 10px; }
.cat-row.all { grid-template-columns: 16px 1fr auto; font-weight: 600; }
.cat-name, .fam-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.count {
  font: 11px var(--mono);
  color: var(--ink-3);
  background: var(--bg);
  border-radius: 999px;
  padding: 1px 7px;
}
.is-active .count { color: var(--accent-ink); background: #d8e8ff; }

.facet { margin-bottom: 4px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; padding: 0 4px; }
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12px;
  color: var(--ink-2);
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 999px;
  padding: 3px 9px;
}
.chip:hover { border-color: var(--ink-3); color: var(--ink); }
.chip.is-active {
  color: var(--accent-ink);
  border-color: var(--accent);
  background: var(--accent-weak);
  font-weight: 600;
}
.chip .count { background: transparent; padding: 0; }

/* ── results_list ──────────────────────────────────────────────────────── */
.results { padding-bottom: 30px; }
.list { list-style: none; margin: 0; padding: 0; }
.group {
  position: sticky; top: 0; z-index: 1;
  display: flex; align-items: baseline; justify-content: space-between;
  padding: 7px 20px 5px;
  background: color-mix(in srgb, var(--bg) 88%, var(--surface));
  backdrop-filter: blur(3px);
  border-bottom: 1px solid var(--border);
  font-size: 12px; font-weight: 700;
  letter-spacing: 0.03em;
  color: var(--ink-2);
}
.group .count { background: transparent; }
.row {
  display: flex; flex-direction: column; gap: 1px;
  padding: 7px 20px;
  border-bottom: 1px solid var(--border-soft);
  cursor: pointer;
}
.row:hover { background: var(--bg); }
.row.is-selected {
  background: var(--accent-weak);
  box-shadow: inset 3px 0 0 var(--accent);
}
.row-top { display: flex; align-items: baseline; justify-content: space-between; gap: 14px; }
.mpn { font: 600 13px var(--mono); letter-spacing: -0.01em; }
.row-top .meta { font-size: 12px; color: var(--ink-2); white-space: nowrap; }
.row-desc { display: flex; justify-content: space-between; gap: 14px; font-size: 12px; }
.row-desc .desc {
  color: var(--ink-2);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.stock { white-space: nowrap; font-weight: 600; }
.stock.s-in { color: var(--ok-ink); }
.stock.s-low { color: var(--warn-ink); }
.stock.s-out { color: var(--out-ink); }

/* ── states (loading / empty / error panels) ───────────────────────────── */
.state-panel {
  margin: 60px auto;
  max-width: 460px;
  text-align: center;
  padding: 28px 32px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
}
.state-title { margin: 0 0 6px; font-size: 15px; font-weight: 700; }
.state-note { margin: 0 0 14px; font-size: 13px; color: var(--ink-2); }
.btn {
  font-size: 13px; font-weight: 600;
  color: var(--accent-ink);
  border: 1px solid var(--accent);
  background: var(--surface);
  border-radius: var(--rad);
  padding: 6px 14px;
}
.btn:hover { background: var(--accent-weak); }

/* ── detail_inspector ──────────────────────────────────────────────────── */
.inspector {
  background: var(--surface);
  border-left: 1px solid var(--border);
  padding: 12px 16px 24px;
}
.ins-h {
  margin: 6px 0 12px;
  font-size: 11px; font-weight: 700;
  letter-spacing: 0.07em; text-transform: uppercase;
  color: var(--ink-3);
}
.ins-empty { color: var(--ink-2); font-size: 13px; }
.ins-note { font-size: 12px; color: var(--ink-3); margin-top: 8px; }
.ins-badge {
  display: inline-block;
  font-size: 11px; font-weight: 700;
  border-radius: 999px;
  padding: 3px 10px;
  margin-bottom: 12px;
}
.ins-badge.ok { color: var(--ok-ink); background: var(--ok-bg); }
.ins-badge.out { color: var(--warn-ink); background: var(--warn-bg); }
.inspector .btn { margin-bottom: 14px; }
.ins-mpn { font: 700 16px var(--mono); letter-spacing: -0.01em; word-break: break-all; }
.ins-desc { margin: 6px 0 12px; font-size: 13px; color: var(--ink-2); }
.ins-path { font-size: 12.5px; margin-bottom: 14px; color: var(--ink-3); }
.ins-path .path {
  color: var(--accent-ink);
  padding: 1px 4px; border-radius: 3px;
}
.ins-path .path:hover { background: var(--accent-weak); text-decoration: underline; }
.specs { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 0; border-top: 1px solid var(--border-soft); }
.spec { display: contents; }
.spec dt {
  font-size: 12px; color: var(--ink-3);
  padding: 7px 12px 7px 0;
  border-bottom: 1px solid var(--border-soft);
  white-space: nowrap;
}
.spec dd {
  margin: 0;
  font-size: 12.5px; font-weight: 600;
  padding: 7px 0;
  border-bottom: 1px solid var(--border-soft);
}

/* ── status_bar ────────────────────────────────────────────────────────── */
.statusbar {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 6px 20px;
  font-size: 12px;
  color: var(--ink-2);
  background: var(--surface);
  border-top: 1px solid var(--border);
}
.status-count { font-weight: 600; }
.status-keys kbd { margin: 0 1px; }

.noscript {
  position: fixed; inset: auto 0 0 0;
  padding: 12px; text-align: center;
  background: var(--out-bg); color: var(--out-ink);
  font-weight: 600;
}

/* ── graceful narrow-viewport degradation (desktop tool first) ─────────── */
@media (max-width: 1180px) {
  .layout { grid-template-columns: 260px minmax(0, 1fr); }
  .inspector { display: none; }
}
@media (max-width: 840px) {
  .layout { grid-template-columns: minmax(0, 1fr); }
  .rail { display: none; }
  .brand-sub, .snapshot { display: none; }
}

content.content:
1	/* PartAtlas — locate app.
2	 *
3	 * Pattern: PAT-LIST-DETAIL (filter-first). Three state owners:
4	 *   query  → search_bar   (S.q)
5	 *   filters→ filter_rail  (S.cat, S.fam, S.dims)
6	 *   select → results_list (S.sel) mirrored by detail_inspector
7	 * Context rule: query and filters compose (AND) and NEVER reset each other or
8	 * the selection. A selection that falls out of the narrowing is annotated in
9	 * the inspector, never dropped.
10	 */
11	(function () {
12	  'use strict';
13	
14	  const $ = (s) => document.querySelector(s);
15	  const app = $('#app');
16	
17	  /* ── phase gate: data must exist because data.js ran before this script ── */
18	  const C = window.CATALOG;
19	  if (!C || !C.parts || !C.parts.length) {
20	    app.dataset.phase = 'error';
21	    $('#state-loading').hidden = true;
22	    $('#state-error').hidden = false;
23	    return;
24	  }
25	
26	  /* ── catalog indexes ──────────────────────────────────────────────────── */
27	  const byId = new Map(C.parts.map((p) => [p.id, p]));
28	  const famName = new Map();
29	  for (const cid of Object.keys(C.families))
30	    for (const f of C.families[cid]) famName.set(f.id, f.name);
31	  const catName = new Map(C.categories.map((c) => [c.id, c.name]));
32	
33	  /* ── state ────────────────────────────────────────────────────────────── */
34	  const S = {
35	    q: '',
36	    cat: null,            // category id | null
37	    fam: null,            // family id | null
38	    dims: { pkgGroup: new Set(), mount: new Set(), tol: new Set(), avail: new Set() },
39	    open: new Set(),      // expanded categories in the rail
40	    sel: null,            // selected part id (roving, survives narrowing)
41	    phase: 'ready',       // ready | empty | error (loading handled in markup)
42	  };
43	
44	  const DIMS = [
45	    { key: 'pkgGroup', label: 'Package group', part: (p) => p.pkgGroup },
46	    { key: 'mount',    label: 'Mount',         part: (p) => p.mount },
47	    { key: 'tol',      label: 'Tolerance',     part: (p) => p.tol,   skip: (v) => v === '—' },
48	    { key: 'avail',    label: 'Availability',  part: (p) => p.avail },
49	  ];
50	
51	  /* ── querying ─────────────────────────────────────────────────────────── */
52	  function tokens() {
53	    return S.q.trim().toLowerCase().split(/\s+/).filter(Boolean);
54	  }
55	
56	  function makeTest(o) { // o: { qt, cat, fam, dims: {key:Set} }
57	    return (p) => {
58	      for (let i = 0; i < o.qt.length; i++) if (!p.hay.includes(o.qt[i])) return false;
59	      if (o.cat && p.cat !== o.cat) return false;
60	      if (o.fam && p.fam !== o.fam) return false;
61	      for (const d of DIMS) {
62	        const set = o.dims[d.key];
63	        if (set && set.size && !set.has(d.part(p))) return false;
64	      }
65	      return true;
66	    };
67	  }
68	
69	  let K = null; // last computed view: { rows, rowIds, catCounts, famCounts, dimCounts }
70	
71	  function compute() {
72	    const qt = tokens();
73	    const dimsAll = { pkgGroup: S.dims.pkgGroup, mount: S.dims.mount, tol: S.dims.tol, avail: S.dims.avail };
74	
75	    const base = C.parts.filter(makeTest({ qt, dims: dimsAll }));
76	    const catCounts = {}, famCounts = {};
77	    for (const p of base) { catCounts[p.cat] = (catCounts[p.cat] || 0) + 1; famCounts[p.fam] = (famCounts[p.fam] || 0) + 1; }
78	    const rows = S.cat || S.fam ? base.filter((p) => (!S.cat || p.cat === S.cat) && (!S.fam || p.fam === S.fam)) : base;
79	
80	    const dimCounts = {};
81	    for (const d of DIMS) {
82	      const dims2 = Object.assign({}, dimsAll, { [d.key]: new Set() });
83	      const t = makeTest({ qt, cat: S.cat, fam: S.fam, dims: dims2 });
84	      const counts = {};
85	      for (const p of C.parts) {
86	        if (!t(p)) continue;
87	        const v = d.part(p);
88	        if (d.skip && d.skip(v)) continue;
89	        counts[v] = (counts[v] || 0) + 1;
90	      }
91	      dimCounts[d.key] = counts;
92	    }
93	
94	    const rowIds = new Set(rows.map((p) => p.id));
95	    return (K = { rows, rowIds, catCounts, famCounts, dimCounts });
96	  }
97	
98	  /* ── helpers ──────────────────────────────────────────────────────────── */
99	  const fmt = (n) => n.toLocaleString('en-US');
100	  function activeFilterCount() {
101	    let n = 0;
102	    if (S.q.trim()) n++;
103	    if (S.cat) n++;
104	    if (S.fam) n++;
105	    for (const k of Object.keys(S.dims)) n += S.dims[k].size;
106	    return n;
107	  }
108	
109	  /* ── region: search_bar ───────────────────────────────────────────────── */
110	  const q = $('#q'), qClear = $('#q-clear');
111	  q.addEventListener('input', () => { S.q = q.value; qClear.hidden = !q.value; render(); });
112	  qClear.addEventListener('click', () => { q.value = ''; S.q = ''; qClear.hidden = true; render(); q.focus(); });
113	
114	  /* ── region: breadcrumb_strip ─────────────────────────────────────────── */
115	  const crumbs = $('#crumbs');
116	  function renderCrumbs() {
117	    const frag = document.createDocumentFragment();
118	    const mk = (label, cls, fn, ariaPressed) => {
119	      const b = document.createElement('button');
120	      b.type = 'button'; b.className = 'crumb ' + cls;
121	      b.textContent = label;
122	      if (ariaPressed !== undefined) b.setAttribute('aria-pressed', ariaPressed ? 'true' : 'false');
123	      b.addEventListener('click', fn);
124	      return b;
125	    };
126	    const sep = () => { const s = document.createElement('span'); s.className = 'crumb-sep'; s.textContent = '›'; return s; };
127	
128	    frag.append(mk('All parts', S.cat ? '' : 'is-active', () => { S.cat = null; S.fam = null; render(); }), sep());
129	    if (S.cat) {
130	      frag.append(mk(catName.get(S.cat), S.fam ? '' : 'is-active', () => { S.fam = null; render(); }), sep());
131	      if (S.fam) frag.append(mk(famName.get(S.fam), 'is-active', () => {}));
132	    } else {
133	      const hint = document.createElement('span');
134	      hint.className = 'crumb-hint'; hint.textContent = 'no category scope';
135	      frag.append(hint);
136	    }
137	
138	    // removable facet chips
139	    for (const d of DIMS) {
140	      for (const v of S.dims[d.key]) {
141	        const chip = document.createElement('button');
142	        chip.type = 'button'; chip.className = 'crumb-chip';
143	        chip.title = 'Remove filter';
144	        chip.innerHTML = `<span>${d.label}: ${v}</span><span class="x">×</span>`;
145	        chip.setAttribute('aria-label', `Remove filter ${d.label} ${v}`);
146	        chip.addEventListener('click', () => { S.dims[d.key].delete(v); render(); });
147	        frag.append(chip);
148	      }
149	    }
150	
151	    if (activeFilterCount() > 0) {
152	      const clear = document.createElement('button');
153	      clear.type = 'button'; clear.className = 'crumb-clear';
154	      clear.textContent = 'Clear all';
155	      clear.addEventListener('click', clearAll);
156	      frag.append(clear);
157	    }
158	    crumbs.replaceChildren(frag);
159	  }
160	
161	  function clearAll() {
162	    S.q = ''; q.value = ''; qClear.hidden = true;
163	    S.cat = null; S.fam = null;
164	    for (const k of Object.keys(S.dims)) S.dims[k].clear();
165	    render();
166	  }
167	
168	  /* ── region: filter_rail ──────────────────────────────────────────────── */
169	  const rail = $('#rail');
170	  function renderRail() {
171	    const frag = document.createDocumentFragment();
172	    const H = (text) => { const h = document.createElement('h2'); h.className = 'rail-h'; h.textContent = text; return h; };
173	
174	    // — collection tree —
175	    frag.append(H('Collection'));
176	    const allBtn = document.createElement('button');
177	    allBtn.type = 'button';
178	    allBtn.className = 'cat-row all' + (S.cat ? '' : ' is-active');
179	    allBtn.setAttribute('aria-pressed', S.cat ? 'false' : 'true');
180	    allBtn.innerHTML = `<span></span><span class="cat-name">All parts</span><span class="count">${fmt(C.parts.length)}</span>`;
181	    allBtn.addEventListener('click', () => { S.cat = null; S.fam = null; render(); });
182	    frag.append(allBtn);
183	
184	    for (const c of C.categories) {
185	      const isOpen = S.open.has(c.id) || S.cat === c.id;
186	      const rowEl = document.createElement('div');
187	      rowEl.className = 'cat-item';
188	      // chevron toggles browsing scope; the name button narrows to the category
189	      const head = document.createElement('div');
190	      head.className = 'cat-head' + (S.cat === c.id ? ' is-active' : '');
191	      const chev = document.createElement('button');
192	      chev.type = 'button';
193	      chev.className = 'chev';
194	      chev.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
195	      chev.setAttribute('aria-label', `${isOpen ? 'Collapse' : 'Expand'} ${c.name} families`);
196	      chev.textContent = isOpen ? '▾' : '▸';
197	      chev.addEventListener('click', () => { S.open.has(c.id) ? S.open.delete(c.id) : S.open.add(c.id); render(); });
198	      const nameBtn = document.createElement('button');
199	      nameBtn.type = 'button';
200	      nameBtn.className = 'cat-btn';
201	      nameBtn.setAttribute('aria-pressed', S.cat === c.id ? 'true' : 'false');
202	      nameBtn.innerHTML = `<span class="cat-name">${c.name}</span><span class="count">${fmt(K.catCounts[c.id] || 0)}</span>`;
203	      nameBtn.addEventListener('click', () => { S.cat = c.id; S.fam = null; render(); });
204	      head.append(chev, nameBtn);
205	      rowEl.append(head);
206	
207	      if (isOpen) {
208	        const listEl = document.createElement('div');
209	        listEl.className = 'fam-list';
210	        for (const f of C.families[c.id]) {
211	          const n = K.famCounts[f.id] || 0;
212	          const fb = document.createElement('button');
213	          fb.type = 'button';
214	          fb.className = 'fam-row' + (S.fam === f.id ? ' is-active' : '');
215	          fb.setAttribute('aria-pressed', S.fam === f.id ? 'true' : 'false');
216	          fb.innerHTML = `<span class="fam-name">${f.name}</span><span class="count">${fmt(n)}</span>`;
217	          fb.addEventListener('click', () => { S.fam = f.id; S.cat = c.id; render(); });
218	          listEl.append(fb);
219	        }
220	        rowEl.append(listEl);
221	      }
222	      frag.append(rowEl);
223	    }
224	
225	    // — facets —
226	    for (const d of DIMS) {
227	      const counts = K.dimCounts[d.key];
228	      const entries = Object.keys(counts)
229	        .filter((v) => !(d.skip && d.skip(v)))
230	        .sort((a, b) => counts[b] - counts[a]);
231	      const active = [...S.dims[d.key]];
232	      const shown = entries.slice(0, 14).concat(active.filter((v) => !entries.slice(0, 14).includes(v)));
233	      const sec = document.createElement('section');
234	      sec.className = 'facet';
235	      sec.append(H(d.label));
236	      const wrap = document.createElement('div');
237	      wrap.className = 'chips';
238	      for (const v of shown) {
239	        const chip = document.createElement('button');
240	        chip.type = 'button';
241	        const on = S.dims[d.key].has(v);
242	        chip.className = 'chip' + (on ? ' is-active' : '');
243	        chip.setAttribute('aria-pressed', on ? 'true' : 'false');
244	        chip.innerHTML = `<span>${v}</span><span class="count">${fmt(counts[v] || 0)}</span>`;
245	        chip.addEventListener('click', () => { on ? S.dims[d.key].delete(v) : S.dims[d.key].add(v); render(); });
246	        wrap.append(chip);
247	      }
248	      sec.append(wrap);
249	      frag.append(sec);
250	    }
251	    rail.replaceChildren(frag);
252	  }
253	
254	  /* ── region: results_list (grouped, chunked, roving selection) ────────── */
255	  const list = $('#list');
256	  const sentinel = $('#sentinel');
257	  const CHUNK = 250;
258	  let groups = [];      // [{catId, famId, name, parts:[…]}]
259	  let cursor = { g: 0, i: 0 };
260	  let io = new IntersectionObserver(onSense, { root: list.parentElement, rootMargin: '600px' });
261	  io.observe(sentinel);
262	
263	  function buildGroups() {
264	    groups = [];
265	    let cur = null;
266	    for (const p of K.rows) {
267	      if (!cur || cur.famId !== p.fam) {
268	        cur = { famId: p.fam, name: `${catName.get(p.cat)} › ${famName.get(p.fam)}`, parts: [] };
269	        groups.push(cur);
270	      }
271	      cur.parts.push(p);
272	    }
273	    cursor = { g: 0, i: 0 };
274	  }
275	
276	  function rowEl(p) {
277	    const li = document.createElement('li');
278	    li.className = 'row' + (S.sel === p.id ? ' is-selected' : '');
279	    li.id = 'opt-' + p.id;
280	    li.setAttribute('role', 'option');
281	    li.setAttribute('aria-selected', S.sel === p.id ? 'true' : 'false');
282	    li.dataset.id = p.id;
283	    li.innerHTML =
284	      `<div class="row-top"><span class="mpn">${p.mpn}</span>` +
285	      `<span class="meta">${p.value}${p.pkg ? ' · ' + p.pkg : ''}</span></div>` +
286	      `<div class="row-desc"><span class="desc">${p.desc}</span>` +
287	      `<span class="stock s-${p.avail.split(' ')[0].toLowerCase()}">${p.avail}${p.stock ? ' · ' + fmt(p.stock) : ''}</span></div>`;
288	    return li;
289	  }
290	
291	  function renderMore() {
292	    if (cursor.g >= groups.length) return false;
293	    const frag = document.createDocumentFragment();
294	    let budget = CHUNK;
295	    while (budget > 0 && cursor.g < groups.length) {
296	      const g = groups[cursor.g];
297	      if (cursor.i === 0) {
298	        const gh = document.createElement('li');
299	        gh.className = 'group'; gh.setAttribute('role', 'presentation');
300	        gh.innerHTML = `<span class="group-name">${g.name}</span><span class="count">${fmt(g.parts.length)}</span>`;
301	        frag.append(gh);
302	      }
303	      while (cursor.i < g.parts.length && budget-- > 0) frag.append(rowEl(g.parts[cursor.i++]));
304	      if (cursor.i >= g.parts.length) { cursor.g++; cursor.i = 0; }
305	    }
306	    list.append(frag);
307	    if (S.sel != null) {
308	      const el = document.getElementById('opt-' + S.sel);
309	      if (el) { list.setAttribute('aria-activedescendant', el.id); el.classList.add('is-selected'); el.setAttribute('aria-selected', 'true'); }
310	    }
311	    return cursor.g < groups.length;
312	  }
313	
314	  function ensureRendered(id) {
315	    while (!document.getElementById('opt-' + id) && renderMore()) { /* chunk until present */ }
316	  }
317	
318	  function onSense(entries) {
319	    if (entries.some((e) => e.isIntersecting) && !list.hidden) renderMore();
320	  }
321	
322	  function renderList() {
323	    const empty = K.rows.length === 0;
324	    $('#state-empty').hidden = !empty;
325	    list.hidden = empty;
326	    sentinel.hidden = empty;
327	    app.dataset.empty = empty ? 'true' : 'false';
328	    if (empty) { list.replaceChildren(); return; }
329	    buildGroups();
330	    list.replaceChildren();
331	    renderMore();
332	  }
333	
334	  list.addEventListener('click', (e) => {
335	    const li = e.target.closest('.row');
336	    if (li) select(Number(li.dataset.id), false);
337	  });
338	
339	  /* ── region: detail_inspector ─────────────────────────────────────────── */
340	  const inspector = $('#inspector');
341	  function renderInspector() {
342	    app.dataset.selected = S.sel != null ? 'true' : 'false';
343	    if (S.sel == null) {
344	      inspector.replaceChildren();
345	      inspector.innerHTML =
346	        `<h2 class="ins-h">Inspector</h2>` +
347	        `<div class="ins-empty"><p>Select a part to inspect it here.</p>` +
348	        `<p class="ins-note">The results list and your narrowing stay exactly where they are — detail never replaces context.</p></div>`;
349	      return;
350	    }
351	    const p = byId.get(S.sel);
352	    const inNarrow = K.rowIds.has(p.id);
353	    const spec = (k, v) => v && v !== '—' ? `<div class="spec"><dt>${k}</dt><dd>${v}</dd></div>` : '';
354	    inspector.innerHTML =
355	      `<h2 class="ins-h">Inspector</h2>` +
356	      `<div class="ins-badge ${inNarrow ? 'ok' : 'out'}">${inNarrow ? '✓ in current narrowing' : '⚠ outside current narrowing'}</div>` +
357	      (inNarrow ? '' : `<button type="button" class="btn reveal">Show in its home context</button>`) +
358	      `<div class="ins-mpn">${p.mpn}</div>` +
359	      `<p class="ins-desc">${p.desc}</p>` +
360	      `<div class="ins-path">` +
361	        `<button type="button" class="path" data-cat="${p.cat}">${catName.get(p.cat)}</button> › ` +
362	        `<button type="button" class="path" data-fam="${p.fam}" data-cat="${p.cat}">${famName.get(p.fam)}</button>` +
363	      `</div>` +
364	      `<dl class="specs">` +
365	        spec('Value', p.value) + spec('Package', p.pkg) + spec('Package group', p.pkgGroup) +
366	        spec('Mount', p.mount) + spec('Tolerance', p.tol) + spec('Rating', p.volt) +
367	        spec('Stock', p.stock === 0 ? '0 — out of stock' : fmt(p.stock) + ' units') +
368	      `</dl>`;
369	    inspector.querySelector('.reveal')?.addEventListener('click', () => {
370	      S.q = ''; q.value = ''; qClear.hidden = true;
371	      for (const k of Object.keys(S.dims)) S.dims[k].clear();
372	      S.cat = p.cat; S.fam = p.fam;
373	      render();
374	    });
375	    inspector.querySelectorAll('.path').forEach((b) => b.addEventListener('click', () => {
376	      S.cat = b.dataset.cat; S.fam = b.dataset.fam || null; render();
377	    }));
378	  }
379	
380	  /* ── selection (context rule: never reset by narrowing) ───────────────── */
381	  function select(id, scroll) {
382	    S.sel = id;
383	    ensureRendered(id);
384	    for (const el of list.querySelectorAll('.row.is-selected')) {
385	      el.classList.remove('is-selected'); el.setAttribute('aria-selected', 'false');
386	    }
387	    const el = document.getElementById('opt-' + id);
388	    if (el) {
389	      el.classList.add('is-selected'); el.setAttribute('aria-selected', 'true');
390	      list.setAttribute('aria-activedescendant', el.id);
391	      if (scroll) el.scrollIntoView({ block: 'nearest' });
392	    }
393	    renderInspector();
394	  }
395	
396	  function moveSelection(delta) {
397	    if (!K.rows.length) return;
398	    const ids = K.rows.map((p) => p.id);
399	    let idx = ids.indexOf(S.sel);
400	    idx = idx === -1 ? (delta > 0 ? 0 : ids.length - 1) : Math.min(ids.length - 1, Math.max(0, idx + delta));
401	    select(ids[idx], true);
402	  }
403	
404	  /* ── region: status_bar ───────────────────────────────────────────────── */
405	  function renderStatus() {
406	    const n = activeFilterCount();
407	    $('#status-count').textContent =
408	      `${fmt(K.rows.length)} of ${fmt(C.parts.length)} parts · ${n} filter${n === 1 ? '' : 's'} active`;
409	  }
410	
411	  /* ── keyboard: / focus, ↑↓ move, Esc clear ────────────────────────────── */
412	  document.addEventListener('keydown', (e) => {
413	    const inInput = e.target === q;
414	    if (e.key === '/' && !inInput) { e.preventDefault(); q.focus(); q.select(); return; }
415	    if (inInput) {
416	      if (e.key === 'Escape') { q.value = ''; S.q = ''; qClear.hidden = true; render(); }
417	      return;
418	    }
419	    if (e.key === 'ArrowDown') { e.preventDefault(); moveSelection(1); }
420	    else if (e.key === 'ArrowUp') { e.preventDefault(); moveSelection(-1); }
421	    else if (e.key === 'Escape') { clearAll(); }
422	  });
423	
424	  $('#empty-clear').addEventListener('click', clearAll);
425	
426	  /* ── initial state (deep-linkable: ?q= &cat= &fam=) ───────────────────── */
427	  const params = new URLSearchParams(location.search);
428	  S.q = params.get('q') || '';
429	  q.value = S.q; qClear.hidden = !S.q;
430	  S.cat = params.get('cat') || null;
431	  S.fam = params.get('fam') || null;
432	  if (S.fam && !S.cat) for (const cid of Object.keys(C.families)) if (C.families[cid].some((f) => f.id === S.fam)) S.cat = cid;
433	
434	  /* ── render + enter ready phase BEFORE first paint ────────────────────── */
435	  function render() {
436	    compute();
437	    renderCrumbs();
438	    renderRail();
439	    renderList();
440	    renderInspector();
441	    renderStatus();
442	    S.phase = K.rows.length ? 'ready' : 'empty';
443	    app.dataset.phase = S.phase;
444	  }
445	
446	  $('#snapshot-label').textContent = `snapshot ${C.generated}`;
447	  $('#state-loading').hidden = true;
448	  render();
449	  q.focus({ preventScroll: true });
450	})();
